1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("empty item list → premium 5 G (only the processing fee)", () => {
7	      const scenario = {
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      };
11	
12	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	    });
14	    it.todo("a single sword → base premium 100 G");
15	    it.todo("a single amulet → base premium 60 G");
16	    it.todo("a single staff → base premium 80 G");
17	    it.todo("a single potion → base premium 40 G");
18	    it.todo("a single rune (component) → base premium 25 G");
19	    it.todo("a single moonstone (component) → base premium 25 G");
20	  });
21	
22	  describe("quote — building block of 3 alike components", () => {
23	    it.todo("2 runes → 50 G base premium");
24	    it.todo("3 runes → 60 G base premium (block applies)");
25	    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
26	    it.todo("7 runes → 175 G base premium");
27	    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
28	    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
29	  });
30	
31	  describe("quote — item-specific modifiers", () => {
32	    it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
33	    it.todo("sword with enchantment 5 → 30 % high-enchantment surcharge applies");
34	    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
35	    it.todo("cursed sword with enchantment 5 → both surcharges apply");
36	  });
37	
38	  describe("quote — policy-wide modifiers", () => {
39	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
40	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
41	    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
42	    it.todo("the customer's second quote → additional 15 % follow-up contract discount");
43	  });
44	
45	  describe("quote — modifier scope on multi-item policies", () => {
46	    it.todo(
47	      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G; curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
48	    );
49	  });
50	
51	  describe("quote — rounding in the MHPCO's favour", () => {
52	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
53	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
54	  });
55	
56	  describe("claim — standard reimbursement", () => {
57	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
58	    it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
59	  });
60	
61	  describe("claim — special clauses", () => {
62	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause only)");
63	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
64	    it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % clause at the threshold)");
65	    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
66	  });
67	
68	  describe("claim — deductible per damage event", () => {
69	    it.todo(
70	      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible once per damaged item)",
71	    );
72	    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
73	  });
74	
75	  describe("claim — insurance sum and cap", () => {
76	    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
77	    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
78	    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
79	    it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value (premium modifiers do not raise the cap)");
80	    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
81	    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
82	  });
83	
84	  describe("claim — multiple items of the same type", () => {
85	    it.todo(
86	      "a policy covers two swords; two sword damage entries → each entry is a separate damage with its own deductible",
87	    );
88	    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
89	  });
90	
91	  describe("errors", () => {
92	    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
93	    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
94	    it.todo("claim references a damage entry with an unknown item type → error");
95	    it.todo("claim contains a damage entry with amount -200 → error");
96	  });
97	
98	  describe("integration examples", () => {
99	    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword (enchantment 3) → premium 165 G");
100	    it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");
101	  });
102	});
